package com.nexusdrive.storage.controller;import com.nexusdrive.storage.service.*;import io.swagger.v3.oas.annotations.Operation;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/chunks")public class ChunkController{private final ChunkStorageService storage;private final ReplicationService replication;public ChunkController(ChunkStorageService s,ReplicationService r){storage=s;replication=r;}@Operation(summary="Store an encrypted chunk")@PutMapping(value="/{id}",consumes=MediaType.APPLICATION_OCTET_STREAM_VALUE)@ResponseStatus(HttpStatus.NO_CONTENT)public void put(@PathVariable String id,@RequestBody byte[] data,@RequestHeader(value="X-Replication-Request",defaultValue="false")boolean replica){storage.put(id,data);if(!replica)replication.replicate(id,data);}@Operation(summary="Read an encrypted chunk")@GetMapping(value="/{id}",produces=MediaType.APPLICATION_OCTET_STREAM_VALUE)public byte[] get(@PathVariable String id){return storage.get(id);}@Operation(summary="Delete an encrypted chunk")@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable String id,@RequestHeader(value="X-Replication-Request",defaultValue="false")boolean replica){storage.delete(id);if(!replica)replication.deleteReplicas(id);}}
